<script lang="ts">
 import { onMount } from 'svelte'; import PageHeader from '$lib/components/PageHeader.svelte'; import { me } from '$lib/api/auth'; import type { MeResponse } from '$lib/api/types'; let user=$state<MeResponse|null>(null),loading=$state(true),errorMessage=$state(''); onMount(async()=>{try{user=(await me()).data}catch(e){errorMessage=e instanceof Error?e.message:'资料加载失败'}finally{loading=false}});
</script>
